const D = { energy:.6, scale:1, density:.5, speed:1, hue:196, x:.5, y:.46, hatch:.5, style:'galvanised', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), rust = (sty === 'rust'), therm = (sty === 'thermal'), dk = (sty === 'chiaroscuro');
const AL = cl(P.alpha, 0, 100);
if (AL > 0.5) {

// ---- the deck streams toward the camera; rods keyed on ABSOLUTE index
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.20 + .22*K.intensity + .20*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.26;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const RP = u*.30*P.scale;                                  // cross-rod pitch
const BP = u*.075*P.scale/(.6 + .8*cl(P.density,0,1));     // load-bar pitch (density = mesh fineness)
const BW = BP*.10, BD = u*.034*P.scale;                    // blade half-thickness / blade depth
const eh = u*.30;                                          // eye height, FIXED
const camZ = S.z*RP;
const camX = u*.10*dB*P.energy;
const camY = -(eh + u*.020*dC*P.energy);
const yaw = .020*dA*P.energy + .013*Math.sin(K.t*.147+1.9);
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.055;
const vcx = cl(P.x,.12,.88)*width, vcy = cl(P.y,.18,.72)*height;
const Z0 = camZ - RP*.6, Z1 = camZ + RP*13;
const rc = Math.floor(S.z);

// a lamp somewhere overhead slides across the deck on incommensurate rates
const lgx = u*.9*Math.sin(K.t*.047) + u*.35*Math.sin(K.t*.113+1.3);
const lgz = camZ + RP*(1.8 + 1.9*Math.sin(K.t*.061) + .9*Math.sin(K.t*.139+2.2));

const AXa = new Float64Array(10), AYa = new Float64Array(10), AZa = new Float64Array(10);
const BXa = new Float64Array(14), BYa = new Float64Array(14);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AXa[i] = X*ca - Z*sa; AYa[i] = Y; AZa[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZa[i], bz = AZa[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BXa[m] = vcx + f*AXa[i]/az; BYa[m] = vcy + f*AYa[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BXa[m] = vcx + f*(AXa[i]+(AXa[j]-AXa[i])*tt)/NEAR;
      BYa[m] = vcy + f*(AYa[i]+(AYa[j]-AYa[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BXa[i], BYa[i]); endShape(CLOSE);
  return true;
}
function pt2(X,Y,Z){
  const dx = X-camX, dy = Y-camY, dz = Z-camZ;
  const rz = dx*sa + dz*ca;
  if (rz <= NEAR) return null;
  return [vcx + f*(dx*ca - dz*sa)/rz, vcy + f*dy/rz, rz];
}
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = wire ? [212, 58, 22] : rust ? [18, 40, 24] : therm ? [252, 58, 12]
           : dk ? [HU, 12, 8] : [(HU+2)%360, 14, 30];
const fogA = wire ? .26 : .66;
function tone(v, tv){
  if (wire)  return [212, 60, cl(12 + 12*v, 8, 34)];
  if (therm) return [cl(256 - 238*v, 10, 260), cl(64 - 14*v, 20, 80), cl(8 + 82*v, 4, 96)];
  if (rust)  return [cl(15 + 18*tv - 4*v, 2, 40), cl(32 + 32*tv - 12*v, 5, 66), cl(6 + 76*v, 4, 92)];
  if (dk)    return [HU, cl(22 - 12*v, 0, 26), cl(2 + 90*Math.pow(v,1.9), 1, 96)];
  return [(HU - 6 + 9*tv + 360)%360, cl(11 - 6*v + 6*tv, 0, 18), cl(9 + 78*v, 4, 95)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a*AL/100);
  else stroke((HU+2)%360, 10, 80, a*.28*AL/100);
}
function fl2(c, a){ fill(c[0], c[1], c[2], (a===undefined?100:a)*AL/100); }
const LTH = rust ? 34 : therm ? 24 : dk ? HU : (HU-166+360)%360;

// ---- the void UNDER the deck: this is the depth cue no other floor has ------------
{
  const NBD = 22;
  noStroke();
  for (let i=0;i<NBD;i++){
    const s = i/(NBD-1);
    const c = tone(cl(.13*Math.pow(s, 1.5) + .02, 0, 1), fr(i*3.1));
    fl2([c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.4, 0, 100)], 88);
    rect(0, vcy + s*(height-vcy) - 1.5, width, (height-vcy)/NBD + 3);
  }
}
// a lower deck + pipes falling away below, on their own parallax rate
if (!wire){
  const DY = u*.95*P.scale;
  for (let k = rc-1; k < rc+7; k++){
    const z0 = k*RP*1.6 + RP*.4, z1 = z0 + RP*.5;
    if (z1 < camZ + NEAR) continue;
    const hz = cl((z0-camZ)/(RP*11), 0, 1);
    const c = mixc(tone(cl((.13 + .10*fr(k*5.1))*(.4+.5*gl), 0, 1), fr(k*2.3)), HAZE, hz*fogA);
    noStroke(); fl2(c, 80);
    poly([-u*2.4, DY, z0, u*2.4, DY, z0, u*2.4, DY, z1, -u*2.4, DY, z1]);
  }
  for (let i=0;i<3;i++){
    const px2 = -u*1.5 + fr(i*7.7+3)*u*3.0, py2 = u*(.42 + .30*fr(i*11.3));
    const c = mixc(tone(cl(.17*(.4+.5*gl), 0, 1), fr(i*3.7)), HAZE, .5*fogA);
    noStroke(); fl2(c, 82);
    poly([px2 - u*.035, py2, camZ, px2 + u*.035, py2, camZ, px2 + u*.035, py2, camZ + RP*12, px2 - u*.035, py2, camZ + RP*12]);
  }
}

// ---- the grating: blades on edge. Grazing => the sides close up and it reads solid;
//      underfoot => it opens and you see straight through into the void.
const i0 = Math.floor((camX - u*2.6)/BP), i1 = Math.ceil((camX + u*2.6)/BP);
const bars = [];
for (let i=i0; i<=i1; i++){
  const X = i*BP;
  const p = pt2(X, 0, camZ + RP*1.2);
  if (!p) continue;
  if (p[0] < -u*.06 || p[0] > width + u*.06) continue;
  bars.push([Math.abs(X - camX), i, X]);
}
bars.sort((a,b) => b[0]-a[0]);                        // outermost first, so near bars win
const NBmax = Math.min(bars.length, 62);
strokeWeight(Math.max(1, u*.0011));
for (let q = bars.length-NBmax; q < bars.length; q++){
  const bd = bars[q], i = bd[1], X = bd[2];
  const tv = fr(i*31.7);
  const sgn = (X >= camX) ? -1 : 1;                   // the blade side that turns toward us
  // blade side (in shadow) — this is what closes the mesh at a distance
  const sv = cl((.09 + .12*tv) * (.4+.5*gl), 0, 1);
  const c2 = mixc(tone(sv, tv), HAZE, .5*fogA);
  if (wire){ noFill(); ink(30); } else { noStroke(); fl2(c2); }
  poly([X + sgn*BW, 0, Z0, X + sgn*BW, BD, Z0, X + sgn*BW, BD, Z1, X + sgn*BW, 0, Z1]);
  // blade top — the bright line that converges on the vanishing point
  const lam = cl(1 - Math.abs(X - lgx)/(u*1.15), 0, 1);
  const tvv = cl((.30 + .52*lam + .10*tv) * (.45+.55*gl), 0, 1);
  const c = mixc(tone(tvv, tv), HAZE, .42*fogA);
  if (wire){ noFill(); ink(52); } else { noStroke(); fl2(c); }
  poly([X - BW, 0, Z0, X + BW, 0, Z0, X + BW, 0, Z1, X - BW, 0, Z1]);
}

// ---- cross rods, twisted, every RP — the second axis of the mesh -------------------
for (let k = rc; k < rc+9; k++){
  const z0 = k*RP, z1 = z0 + BP*.22;
  if (z1 < camZ + NEAR) continue;
  const pk = pt2(camX, 0, z0);
  if (!pk) continue;
  if (Math.abs(f*(BP*.22)/pk[2]) < .7) break;          // sub-pixel: stop, the mesh has merged
  const hz = cl((z0-camZ)/(RP*11), 0, 1);
  const tvr = fr(k*17.3);
  const lam = cl(1 - Math.abs(z0 - lgz)/(RP*3.2), 0, 1);
  const c = mixc(tone(cl((.26 + .46*lam + .08*tvr) * (.45+.55*gl), 0, 1), tvr), HAZE, hz*fogA);
  if (wire){ noFill(); ink(44); } else { noStroke(); fl2(c); }
  poly([-u*2.6, -BD*.16, z0, u*2.6, -BD*.16, z0, u*2.6, -BD*.16, z1, -u*2.6, -BD*.16, z1]);
  // panel joint: a heavier bearing bar every few rods, seeded so it is NOT periodic
  if (fr(k*7.9) < .34){
    const c3 = mixc(tone(cl((.34 + .34*lam) * (.45+.55*gl), 0, 1), tvr), HAZE, hz*fogA);
    if (!wire){ noStroke(); fl2(c3); }
    poly([-u*2.6, -BD*.22, z0 - BP*.16, u*2.6, -BD*.22, z0 - BP*.16,
          u*2.6, -BD*.22, z0 + BP*.34, -u*2.6, -BD*.22, z0 + BP*.34]);
  }
}

// ---- an open hatch: a hole straight through the deck, seeded per panel -------------
if (P.hatch > .02 && !wire){
  for (let k = rc; k < rc+6; k++){
    if (fr(k*23.1+5) > cl(P.hatch,0,1)*.34) continue;
    const hx = -u*1.2 + fr(k*13.7)*u*2.4, hw = u*.30*P.scale, hd = RP*.52;
    const z0 = k*RP + RP*.2;
    if (z0 + hd < camZ + NEAR) continue;
    noStroke(); fl2(therm ? [252,60,6] : dk ? [HU,10,2] : [(HU+2)%360, 16, 3], 92);
    poly([hx-hw, -BD*.30, z0, hx+hw, -BD*.30, z0, hx+hw, -BD*.30, z0+hd, hx-hw, -BD*.30, z0+hd]);
    const c = mixc(tone(cl(.42*(.45+.55*gl), 0, 1), .5), HAZE, .2*fogA);
    ink(58); noFill(); strokeWeight(Math.max(1.2, u*.0022));
    poly([hx-hw, -BD*.30, z0, hx+hw, -BD*.30, z0, hx+hw, -BD*.30, z0+hd, hx-hw, -BD*.30, z0+hd]);
    noStroke(); fl2(c);                                       // the lid, folded back on its hinge
    poly([hx-hw, -BD*.30, z0, hx+hw, -BD*.30, z0, hx+hw, -u*.26*P.scale, z0 - hd*.30, hx-hw, -u*.26*P.scale, z0 - hd*.30]);
    strokeWeight(Math.max(1, u*.0011));
  }
}

// ---- light pooling on the bar tops (partial frame, ADD, low alpha) -----------------
if (!wire && AL > 8){
  push(); blendMode(ADD); noStroke();
  for (let i=3;i>=1;i--){
    fill(LTH, therm?60:22, 100, cl((1.8 + 3.6*gl)*AL/100, 0, 12));
    poly([lgx - u*.55*i*.5, -BD*.05, lgz - RP*.9*i*.5, lgx + u*.55*i*.5, -BD*.05, lgz - RP*.9*i*.5,
          lgx + u*.55*i*.5, -BD*.05, lgz + RP*.9*i*.5, lgx - u*.55*i*.5, -BD*.05, lgz + RP*.9*i*.5]);
  }
  pop(); blendMode(BLEND);
}
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
}
